components-block-next-tabs--tabs-default.js:
import { registerWebComponents } from '@domg-wc/common';
import { VlTitleComponent } from '@domg-wc/components/atom';
import { VlTabComponent, VlTabPanelComponent, VlTabsComponent } from '@domg-wc/components/block/next';

registerWebComponents([VlTabsComponent, VlTabComponent, VlTabPanelComponent, VlTitleComponent]);

// vl-tab-click volgt op een klik, Enter of spatie op een tab (niet op de pijltjestoetsen);
// event.detail.tab is de vl-tab-next.
document.querySelector('vl-tabs-next').addEventListener('vl-tab-click', (event) => {
    console.log(event.detail.tab.id);
});

components-block-next-tabs--tabs-horizon.js:
import { registerWebComponents } from '@domg-wc/common';
import { VlTabLinkComponent, VlTabsComponent } from '@domg-wc/components/block/next';

registerWebComponents([VlTabsComponent, VlTabLinkComponent]);

// vl-tab-link-click volgt op een klik op een link; de browser navigeert zelf naar href.
document.querySelector('vl-tabs-next').addEventListener('vl-tab-link-click', (event) => {
    console.log(event.detail.tab.href);
});
